"""Site-wide generated files: the MDX wrappers, the overview, the sidebar entries, sensor.css and sensor-page.js."""
from __future__ import annotations

import json
import re

from .assets import EXTRA_DARK, EXTRA_LIGHT
from .sensor_header import HEADER_PARTS
from .sensor_parts import PARTS, PLOTLY_LOCAL, rig_json

SENSOR_BASE = "/sensors/"  # the Sensor wiki; old /benchmark/sensors/ addresses redirect here (site/src/data/moved.json)


def card_for(slug: str, p: dict) -> dict:
    """Overview card: photo, maker, short name, type and tags. The card's own fields win over the page's full title and maker."""
    h = p["header"]
    img = h["image"]
    m = h.get("maker", {})
    card = p["card"]
    return {"title": card.get("name", p["title"]), "href": f"{SENSOR_BASE}{slug}/", "image": f"/media/sensors/{slug}/{img['file']}",
            "alt": img["alt"], "maker": card.get("maker") or (m.get("name") if m.get("url") else None), "type": h["type"], "tags": card["tags"]}


def mdx(slug: str, p: dict) -> str:
    q = lambda t: json.dumps(t, ensure_ascii=False)
    plist = HEADER_PARTS if p.get("header") else PARTS
    body = "".join(f'## {h}\n\n<SensorPage sensor="{slug}" part="{k}" />\n\n' for h, k in plist)
    extra = f"sensor: {slug}\n" if p.get("header") else ""
    lead = "" if p.get("header") else f'<SensorPage sensor="{slug}" part="lead" />\n\n'
    return (f"---\ntitle: {q(p['title'])}\ndescription: {q(p['description'])}\npageType: example\nwide: true\n{extra}---\n\n"
            f"{{/* Generated by export_sensor.py. Edit the data, not this file. */}}\nimport SensorPage from '../../../components/SensorPage.astro';\n\n"
            f"{lead}{body}")


def site_css(page_css: str, header_css: str) -> str:
    """page.css without the page chrome, scoped to .sp, with tokens taken from Starlight."""
    lines = page_css.splitlines()
    i = next(n for n, l in enumerate(lines) if l.startswith(".chips{"))
    body = "\n".join(l for l in lines[i:] if not l.startswith((".cards", "@media(max-width:1250px)")))
    tok = ("--bg:var(--sl-color-bg);--ink:var(--sl-color-text);--strong:var(--sl-color-white);--muted:var(--sl-color-gray-3);--line:var(--sl-color-hairline);"
           "--soft:var(--sl-color-bg-nav);--accent:var(--sl-color-accent);--accent-low:var(--sl-color-accent-low);--accent-high:var(--sl-color-accent-high);")
    dark, light = EXTRA_DARK + ";", EXTRA_LIGHT + ";"
    return (f"/* Generated by export_sensor.py. */\n.sp{{{tok}{dark}font-variant-numeric:tabular-nums}}\n:root[data-theme='light'] .sp{{{light}}}\n"
            f".sp{{\n{body}\n}}\n.sp{{\n{header_css}\n}}\n.sp + * {{margin-top:1.25rem}}\n.sp .chart svg{{max-width:44rem}}\n.sp .sensorimg{{margin:0 0 1rem;max-width:26rem}}\n.sp .sensorimg img{{display:block;width:100%;border-radius:.6rem;background:#fff;border:1px solid var(--line)}}\n.sp .sensorimg figcaption{{font-size:.8rem;color:var(--muted);margin-top:.35rem}}\n")


FOLD_JS = """
function spOpenHash(){var t=location.hash&&document.getElementById(location.hash.slice(1));if(t&&t.tagName==='DETAILS')t.open=true}
addEventListener('hashchange',spOpenHash);spOpenHash();
document.querySelectorAll('[data-rt]').forEach(function(b){b.onclick=function(){document.querySelectorAll('[data-rt]').forEach(function(o){o.setAttribute('aria-selected',o===b)});document.querySelectorAll('[data-rp]').forEach(function(p){p.hidden=p.dataset.rp!==b.dataset.rt});dispatchEvent(new Event('resize'))}});
if(matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('.sp video').forEach(function(v){v.removeAttribute('autoplay');v.pause()});
"""

def spot(js: str) -> str:
    """Plain time text and a speed control for the report's player, on the site only."""
    a = "return Math.round(pct) + ' % \\u00b7 ' + when + s.unit + ' ' + (i + 1) + ' / ' + n;"
    b = "var f = (ts - t0) / 12000, i = i0;"
    if a not in js or b not in js:
        raise RuntimeError("the MVIS player changed; update spot()")
    return (js.replace("&#9654; Play", "&#9654;&#xFE0E; Play").replace(a, "return t ? t[i].toFixed(1) + ' s of ' + t[n - 1].toFixed(1) + ' s' : (i + 1) + ' of ' + n;")
            .replace(b, "var f = (ts - t0) * (window.SP_SPEED || 1) / 12000, i = i0;"))


def site_js(progress: str, page_js: str, views_js: str = "") -> str:
    """The page script: MVIS's canvas views player (calibration process), the older Plotly progress player for
    pages whose runs predate it, and the sensor map."""
    return ("// Generated by export_sensor.py: MVIS's canvas views, the MVIS report's progress player and the sensor map.\n" + views_js + "\n"
            "const spData = document.getElementById('sp-data');\nif (spData) {\n"
            "const spD = JSON.parse(spData.textContent);\nwindow.RIGS = spD.rigs; window.PROCS = spD.procs.map(() => null); window.PROC_URLS = spD.procs; window.PLOTLY_URL = spD.plotly;\n"
            "new MutationObserver(() => document.dispatchEvent(new Event('themechange'))).observe(document.documentElement, { attributes: true, attributeFilter: ['data-theme'] });\n"
            + spot(progress) + "\n" + page_js + FOLD_JS + "\n}\n")


def sensor_groups(pub: dict) -> list[dict]:
    """Sensors by group, in site order: [{"title", "slugs"}]. A sensor outside the known groups is an error, not a gap."""
    groups = {g["id"]: {"title": g["title"], "slugs": []} for g in pub["groups"]}
    for slug, p in pub["sensors"].items():
        g = p.get("group")
        if g not in groups:
            raise ValueError(f"{slug}: unknown group {g}")
        groups[g]["slugs"].append(slug)
    return [g for g in groups.values() if g["slugs"]]


def sensor_nav(pub: dict) -> list[dict]:
    """Sidebar entries in the same order as the overview. Written to site/src/data/sensor-nav.json."""
    return [{"label": pub["sensors"][s]["title"], "link": f"{SENSOR_BASE}{s}/", "group": g["title"]}
            for g in sensor_groups(pub) for s in g["slugs"]]


def overview_mdx(pub: dict) -> str:
    """Sensors overview: jump links, then a heading and a grid per group. Headings put the groups in "On this page"."""
    groups = sensor_groups(pub)
    jump = " · ".join(f"[{g['title']}](#{re.sub(r'[^a-z0-9]+', '-', g['title'].lower())})" for g in groups)
    body = "".join(f"## {g['title']}\n\n<SensorGrid slugs={{{json.dumps(g['slugs'])}}} />\n\n" for g in groups)
    return ("---\ntitle: Sensor wiki\ndescription: One page per sensor, in the same format, with the calibration process, a map of the solved rig and full results.\npageType: reference\nwide: true\n---\n\n"
            "{/* Generated by export_sensor.py. */}\nimport SensorGrid from '../../../components/SensorGrid.astro';\n\n"
            "Cameras and IMUs calibrated with MVIS. Each page has the sensor's specs and sources, the calibration process, a map of the solved rig and full results.\n\n"
            f"{jump}\n\n{body}"
            ":::note[What these pages show]\nEach page shows what MVIS solved, with any repeatability we have, and says when no independent source exists. "
            "They have no scores, and they aren't part of the [results tables](/benchmark/results/).\n:::\n")




def sensor_json(slug: str, p: dict, parts: dict, vs: list) -> dict:
    """site/src/data/sensors/<slug>.json, before the arrow glyph fix the writer applies."""
    return {"title": p["title"], "parts": parts, "rigs": [rig_json(v) for v in vs], "procs": [None if v.get("views") else f"/media/sensors/{slug}/process{i}.json" for i, v in enumerate(vs)], "plotly": PLOTLY_LOCAL,
            "card": card_for(slug, p)}
